{"arguments":"p_identity_hash text, p_ip_hash text","definition":"CREATE OR REPLACE FUNCTION public.record_login_failure(p_identity_hash text, p_ip_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                      declare
                        v_now timestamptz := now();
                          v_account public.login_account_security%rowtype;
                            v_ip public.login_ip_security%rowtype;
                            begin
                              insert into public.login_account_security(identity_hash, failed_attempts, first_failed_at, last_failed_at, last_ip_hash)
                                values (p_identity_hash, 0, v_now, v_now, p_ip_hash)
                                  on conflict (identity_hash) do nothing;
                                    select * into v_account from public.login_account_security where identity_hash = p_identity_hash for update;

                                      if v_account.locked_until is not null and v_account.locked_until > v_now then
                                          -- Existing lock remains in force; do not extend it with further attempts.
                                              null;
                                                else
                                                    if v_account.first_failed_at is null or v_account.first_failed_at < v_now - interval '24 hours' or (v_account.locked_until is not null and v_account.locked_until <= v_now) then
                                                          v_account.failed_attempts := 0;
                                                                v_account.first_failed_at := v_now;
                                                                      v_account.locked_until := null;
                                                                          end if;
                                                                              v_account.failed_attempts := v_account.failed_attempts + 1;
                                                                                  v_account.last_failed_at := v_now;
                                                                                      v_account.last_ip_hash := p_ip_hash;
                                                                                          if v_account.failed_attempts >= 5 then v_account.locked_until := v_now + interval '24 hours'; end if;
                                                                                              update public.login_account_security set failed_attempts=v_account.failed_attempts, first_failed_at=v_account.first_failed_at,
                                                                                                    last_failed_at=v_account.last_failed_at, locked_until=v_account.locked_until, last_ip_hash=p_ip_hash
                                                                                                          where identity_hash=p_identity_hash;
                                                                                                            end if;

                                                                                                              insert into public.login_ip_security(ip_hash, failed_attempts, window_started_at, last_failed_at)
                                                                                                                values (p_ip_hash, 0, v_now, v_now)
                                                                                                                  on conflict (ip_hash) do nothing;
                                                                                                                    select * into v_ip from public.login_ip_security where ip_hash = p_ip_hash for update;
                                                                                                                      if v_ip.locked_until is not null and v_ip.locked_until > v_now then
                                                                                                                          null;
                                                                                                                            else
                                                                                                                                if v_ip.window_started_at is null or v_ip.window_started_at < v_now - interval '15 minutes' or (v_ip.locked_until is not null and v_ip.locked_until <= v_now) then
                                                                                                                                      v_ip.failed_attempts := 0;
                                                                                                                                            v_ip.window_started_at := v_now;
                                                                                                                                                  v_ip.locked_until := null;
                                                                                                                                                      end if;
                                                                                                                                                          v_ip.failed_attempts := v_ip.failed_attempts + 1;
                                                                                                                                                              v_ip.last_failed_at := v_now;
                                                                                                                                                                  if v_ip.failed_attempts >= 20 then v_ip.locked_until := v_now + interval '1 hour'; end if;
                                                                                                                                                                      update public.login_ip_security set failed_attempts=v_ip.failed_attempts, window_started_at=v_ip.window_started_at,
                                                                                                                                                                            last_failed_at=v_ip.last_failed_at, locked_until=v_ip.locked_until where ip_hash=p_ip_hash;
                                                                                                                                                                              end if;

                                                                                                                                                                                return jsonb_build_object(
                                                                                                                                                                                    'account_attempts', v_account.failed_attempts,
                                                                                                                                                                                        'account_locked_until', v_account.locked_until,
                                                                                                                                                                                            'ip_attempts', v_ip.failed_attempts,
                                                                                                                                                                                                'ip_locked_until', v_ip.locked_until
                                                                                                                                                                                                  );
                                                                                                                                                                                                  end;
                                                                                                                                                                                                  $function$
"}
